    function loadModule(file, req, m) {
        const src = fs.readFileSync(file, 'utf8');
        const names = Object.keys(m);
        const fn = new Function('module', 'exports', 'require', 'globalThis',
            names.join(','), src +
            '\n;return { action: action, checksRollup: checksRollup, rollupDetail: rollupDetail, mergeStateOf: mergeStateOf, labelNames: labelNames };');
        const sandbox = {};
        const args = [{}, {}, req, sandbox];
        names.forEach(n => args.push(m[n]));
        const ret = fn.apply(sandbox, args);
        return ret;
    }
    const base = loadModule('/tmp/mergeBot.base.js', makeRequire(), mods);
    const head = loadModule('/tmp/mergeBot.head.js', makeRequire(), mods);
    return { base, head };
}

