    const capB = captured.slice();
    captured = [];
    console.log = origLog;

    const aOut = JSON.stringify({ err: errA && errA.message, res: resA, cap: capA });
    const bOut = JSON.stringify({ err: errB && errB.message, res: resB, cap: capB });
    if (aOut !== bOut) {
