{"content":"// Verify tracker call SEQUENCE equality base vs head for key scenarios.
const fs = require('fs');
const vm = require('vm');

function loadModule(file, m) {
    const src = fs.readFileSync(file, 'utf8');
    const names = Object.keys(m);
    const fn = new Function('module', 'exports', 'require', names.join(','),
        src + '\n;return { action: action };');
    const args = [{}, {}, function () { return {}; }];
    names.forEach(n => args.push(m[n]));
    return fn.apply({}, args);
}

function scenario(name, mkMods, params) {
    const seqA = [], seqB = [];
    const base = loadModule('/tmp/mergeBot.base.js', mkMods(seqA));
    const head = loadModule('/tmp/mergeBot.head.js', mkMods(seqB));
    const orig = console.log; console.log = () => {};
    let rA, eA, rB, eB;
    try { rA = base.action(params); } catch (e) { eA = e; }
    try { rB = head.action(params); } catch (e) { eB = e; }
    console.log = orig;
    const same = JSON.stringify(seqA) === JSON.stringify(seqB) &&
        JSON.stringify({ a: rA, e: eA && eA.message }) === JSON.stringify({ a: rB, e: eB && eB.message });
    console.log((same ? '✅' : '❌') + ' ' + name + (same ? '' : '\n  base: ' + JSON.stringify(seqA) + '\n  head: ' + JSON.stringify(seqB)));
    return same;
}

const now = Date.now();
const iso = h => new Date(now - h * 3600000).toISOString();
const rec = seq => name => (...args) => { seq.push({ name, args: args[0] }); return '{}'; };

function mkMods(seq, opts) {
    opts = opts || {};
    const api = {};
    ['github_list_workflow_runs', 'github_list_prs', 'github_get_pr',
     'github_get_commit_check_runs', 'github_merge_pr', 'github_add_labels',
     'github_remove_label', 'cli_execute_command'].forEach(n => api[n] = rec(seq)(n));
    api.github_list_prs = a => {
        seq.push({ name: 'github_list_prs', args: a });
        if (a.state === 'merged') return JSON.stringify(opts.merged || []);
        return JSON.stringify(opts.open || []);
    };
    api.github_get_pr = a => {
        seq.push({ name: 'github_get_pr', args: a });
        return JSON.stringify(opts.pr || {});
    };
    api.github_get_commit_check_runs = a => {
        seq.push({ name: 'github_get_commit_check_runs', args: a });
        return JSON.stringify(opts.cr || { check_runs: [] });
    };
    api.github_list_workflow_runs = a => {
        seq.push({ name: 'github_list_workflow_runs', args: a });
        if (a.workflowId === 'machine-sm.yml') return JSON.stringify(opts.sm || { workflow_runs: [] });
        if (a.workflowId === 'ci.yml') return JSON.stringify(opts.ci || { workflow_runs: [] });
        return JSON.stringify(opts.all || { workflow_runs: [] });
    };
    api.github_merge_pr = a => { seq.push({ name: 'github_merge_pr', args: a }); return JSON.stringify(opts.mergeRes || { merged: true }); };
    api.github_add_labels = a => { seq.push({ name: 'github_add_labels', args: a }); if (opts.addThrows) throw new Error(opts.addThrows); return '{}'; };
    api.github_remove_label = a => { seq.push({ name: 'github_remove_label', args: a }); if (opts.removeThrows) throw new Error(opts.removeThrows); return '{}'; };
    api.cli_execute_command = a => { seq.push({ name: 'cli_execute_command', args: a }); return ''; };
    return api;
}

let ok = true;
const prOpen = (n, labels, ms, sha) => ({ number: n, state: 'OPEN', draft: false, mergeable: true, mergeable_state: ms || 'clean', head: { sha: sha || ('s' + n) }, labels: labels.map(x => ({ name: x })) });
const lbl = (...xs) => xs.map(x => ({ name: x }));

ok &= scenario('merge path call order', s => mkMods(s, {
    open: [{ number: 3, labels: lbl('pr_approved', 'ai_validating'), head: { sha: 's3' } }],
    pr: prOpen(3, ['pr_approved', 'ai_validating']),
    cr: { check_runs: [{ status: 'COMPLETED', conclusion: 'SUCCESS' }] }
}), { jobParams: { repo: 'a/b' } });

ok &= scenario('latch path call order', s => mkMods(s, {
    open: [{ number: 4, labels: lbl('ai_validating'), head: { sha: 's4' } }],
    pr: prOpen(4, ['ai_validating']),
    cr: { check_runs: [{ status: 'COMPLETED', conclusion: 'SUCCESS' }] }
}), { jobParams: { repo: 'a/b' } });

ok &= scenario('stale unarm + self-tick order', s => mkMods(s, {
    open: [{ number: 5, labels: lbl('pr_approved', 'ai_validating'), head: { sha: 's5' } },
           { number: 6, labels: lbl('pr_approved'), head: { sha: 's6' } }],
    pr: null, cr: { check_runs: [{ status: 'IN_PROGRESS', conclusion: null, started_at: iso(3) }] }
}), { jobParams: { repo: 'a/b' } });

ok &= scenario('404 fallback listing order', s => mkMods(s, {
    open: [{ number: 7, labels: lbl('pr_approved'), head: { sha: 's7' } }],
    pr: prOpen(7, ['pr_approved']),
    sm: { message: 'Not Found' },
    all: { workflow_runs: [{ path: '.github/workflows/machine-sm.yml', status: 'queued', created_at: iso(1) }] }
}), { jobParams: { repo: 'a/b' } });

ok &= scenario('merged slot holder probe order', s => mkMods(s, {
    open: [{ number: 11, labels: lbl('pr_approved', 'ai_validated'), head: { sha: 's11' } }],
    merged: [{ number: 10, merged_at: iso(1), labels: lbl('ai_validating', 'pr_approved') }],
    pr: prOpen(11, ['pr_approved', 'ai_validated']),
    cr: { check_runs: [{ status: 'COMPLETED', conclusion: 'SUCCESS' }] }
}), { jobParams: { repo: 'a/b' } });

console.log(ok ? 'ALL CALL SEQUENCES IDENTICAL' : 'CALL SEQUENCE DIFFERENCES');
process.exit(ok ? 0 : 1);
